import {buildTodayFacts,todayFactsChanged,nextTodayFactBoundary,type TodayRawTodo} from '../../../shared/today-facts.mjs';
import {todayAnswer} from '../today-advice.mjs';
const parameters=new URLSearchParams(location.search),key=`sidekick-today-ui-${parameters.get('todayCase')||'default'}`;
let version=parameters.has('todayUpgrade')?3:5,latest:any=null,lastSuccess:any=null,ticks=0,initialized=false,reconcileReads=0,readCount=0;
const saved=parameters.has('todayFixture')?sessionStorage.getItem(key):null;if(saved){const value=JSON.parse(saved);latest=value.latest;lastSuccess=value.lastSuccess;version=value.version;initialized=true;}
function persist(){if(parameters.has('todayFixture'))sessionStorage.setItem(key,JSON.stringify({latest,lastSuccess,version}));}
function facts(rows:unknown[],zone:string,id='current',at=Date.now()){return buildTodayFacts({snapshotId:id,anchorAtMs:at,timeZone:zone,rawTodos:rows as TodayRawTodo[]});}
function run(rows:unknown[],zone:string,id:string,status='running',at=Date.now()){const f=facts(rows,zone,id,at);return {id,agentId:'advisor',purpose:'today_advice',status,snapshot:{todayFacts:f},result:status==='succeeded'?{kind:'today_advice',version:1,...todayAnswer(f,true)}:null,errorCode:status==='failed'?'MODEL_SERVICE':null,createdAtMs:at,finishedAtMs:status==='running'?null:at+1000};}
export function configureTodayRows(rows:unknown[],zone:string,extend=false){if(!rows.length||!parameters.has('todayBoundary')&&!parameters.has('todayBoundaryOwnership'))return;const row=(rows as TodayRawTodo[]).find(todo=>todo.id==='today-action')||(rows[0] as TodayRawTodo);row.data.due={atMs:Date.now()+(extend?5000:2500),timeZone:zone,localText:'合成短边界'};row.version++;}
export function todayFixture(command:string,args:Record<string,unknown>|undefined,rows:unknown[],zone:string){
 if(!['read_today_advice','start_today_advice','cancel_today_advice','read_today_storage_status','confirm_today_storage_upgrade'].includes(command))return;
 if(!initialized){initialized=true;if(parameters.has('todayHistoryFailure')||parameters.has('todayHistorySuccess')){lastSuccess=run(rows,zone,'today-ui-success','succeeded',Date.now()-600000);latest=parameters.has('todayHistoryFailure')?run(rows,zone,'today-ui-failure','failed',Date.now()-300000):structuredClone(lastSuccess);if(parameters.has('todayStale')&&rows.length){const row=rows[0] as TodayRawTodo;row.data.title='合成事项已更新，请重新核对建议';row.version++;}}persist();}
 if(command==='read_today_storage_status')return {root:'/fixture/sidekick',workspaceId:'c'.repeat(64),version,targetVersion:5,confirmationToken:version<5?'d'.repeat(64):null};
 if(command==='confirm_today_storage_upgrade'){const input=args?.input as {confirmed:boolean;confirmationToken:string};if(!input?.confirmed||input.confirmationToken!=='d'.repeat(64)||version>=5)throw {code:'TODAY_UPGRADE_STALE',message:'合成场景：确认已过期，请重新读取。'};if(parameters.has('todayUpgradeBackup'))throw {code:'MCP_BACKUP_FAILED',message:'合成场景：备份未确认，未执行升级。'};version=5;persist();if(parameters.has('todayUpgradeUnknown'))throw {code:'TODAY_SCHEMA_UNCERTAIN',message:'合成场景：升级结果未确认，请关闭并重开核对。'};return {fromVersion:3,toVersion:5,backup:'backups/before-schema-5-1-2.sqlite'};}
 if(command==='start_today_advice'){if(version<5)throw {code:'TODAY_SCHEMA_REQUIRED',message:'请先升级今日建议存储。'};if(latest?.status==='running')throw {code:'RUNTIME_BUSY',message:'合成任务正在运行。'};if(!facts(rows,zone).counts.open)throw {code:'TODAY_EMPTY',message:'当前没有开放事项。'};latest=run(rows,zone,`today-ui-${crypto.randomUUID()}`);if(parameters.has('todayPreparing')){const full=latest.snapshot.todayFacts;latest.snapshot={todayPreparation:{version:1,input:{snapshotId:full.snapshotId,anchorAtMs:full.anchorAtMs,timeZone:full.timeZone,rawTodos:full.rawTodos}}};}ticks=0;persist();return latest;}
 if(command==='cancel_today_advice'){if(latest?.id!==args?.id)throw {code:'NOT_FOUND',message:'合成任务不存在。'};if(latest.status==='running'){latest.status='cancelled';latest.errorCode='CANCELLED';latest.finishedAtMs=Date.now();}persist();return latest;}
 if(command==='read_today_advice'){if(parameters.has('todayReadErrorAlternating')&&++reconcileReads%2===0)throw {code:'WORKSPACE_IO',message:'合成场景：重新核对事实暂时失败。'};if(parameters.has('todayReconcileReadError')&&++reconcileReads===2)throw {code:'WORKSPACE_IO',message:'合成场景：重新核对事实暂时失败。'};if(parameters.has('todayReadError'))throw {code:'WORKSPACE_IO',message:'合成场景：事实读取暂时失败。'};if(latest?.status==='running'&&!parameters.has('todayPreparing')&&++ticks>=(parameters.has('todaySlow')?100:2)){latest.status=parameters.has('todayFailure')?'failed':'succeeded';latest.finishedAtMs=Date.now();latest.errorCode=latest.status==='failed'?'MODEL_SERVICE':null;if(latest.status==='succeeded'){latest.result={kind:'today_advice',version:1,...todayAnswer(latest.snapshot.todayFacts,true)};if(parameters.has('todayEmptyAdvice'))latest.result.ranking=[];lastSuccess=structuredClone(latest);}persist();}const current=facts(rows,zone);readCount++;if(parameters.has('todayBoundaryOwnership'))console.debug(`N3_SYNTHETIC_TODAY_READ ${readCount} ${Date.now()}`);const response={facts:current,factsValidUntilMs:nextTodayFactBoundary(current),latest,lastSuccess,latestStale:latest?.snapshot.todayPreparation?null:latest?todayFactsChanged(latest.snapshot.todayFacts,current):false,lastSuccessStale:lastSuccess?todayFactsChanged(lastSuccess.snapshot.todayFacts,current):false,storageVersion:version};if(parameters.has('todayReadHold')&&latest?.status==='running'){const delayed=structuredClone(response);return new Promise(resolve=>setTimeout(()=>resolve(delayed),2000));}return response;}
}
